    switch (type(value)) {
        case 'RegExp':
            return new RegExp(value);
        case 'Array':
        case 'Object': {
            const cloneObj = new value.constructor();
            for (const key in value) {
                if (value.hasOwnProperty(key)) {
                    cloneObj[key] = deepClonePredicate(value[key]); // 递归拷贝  
                }
            }
            return cloneObj;
        }
        case 'Date': {
            return new Date(value);
        }
    }
    return value;
